INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  2743,
  'S',
  '4401017',
  'Servicio de asistencia técnica a las actuaciones y  decisiones judiciales de la justicia transicional y restaurativa',
  'Incluye los procesos de acompañamiento técnico que  requiera la magistratura de la Jurisdicción Especial para la Paz para seguir los postulados de justicia transicional y de justicia restaurativa en sus decisiones, contemplando las verificaciones técnicas necesarias para la toma de decisiones, los mecanismos para el monitoreo y seguimiento de decisiones en diferentes momentos procesales, y la sistematización y apropiación social de las sentencias como contribución a la construcción de una paz estable y duradera. Así, por ejemplo, las salas, secciones y Tribunal de la JEP requieres apoyo técnico para: i) verificar la realización de trabajos, obras o actividades con contenido reparador por parte de los comparecientes de FARC, durante su permanencia en zonas veredales transitorias o espacios territoriales de capacitación y reincorporación, para efectos de descontar tiempo de cumplimiento de la sanción propia a que hubiere lugar; ii) hacer monitoreo y seguimiento  quienes accedieron a libe',
  NULL,
  195,
  NULL,
  NULL,
  NULL,
  'N',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00');
INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  2744,
  'S',
  '4401011',
  'Servicio de asistencia técnica a la verificación de las intervenciones con contenido reparador',
  'La Jurisdicción Especial para la Paz verifica la realización de trabajos, obras o actividades con contenido reparador por parte de los comparecientes de FARC, durante su permanencia en zonas veredales transitorias o espacios territoriales de capacitación y reincorporación, para efectos de descontar tiempo de cumplimiento de la sanción propia a que hubiere lugar. Esto de acuerdo Acto Legislativo 01 del 4 de Abril de 2017, art. 134:  DESCUENTO DE LA SANCIÓN PROPIA. Respecto a los integrantes de las FARC-EP acreditados por el Gobierno Nacional, el período de permanencia en las Zonas Veredales Transitorias de Normalización (ZVTN) o en una ubicación territorial perfectamente definida y verificable, será considerado en su caso como tiempo de cumplimiento de la sanción propia, siempre que durante dicha permanencia se hubieran realizado trabajos, obras o actividades con contenido reparador.Parágrafo. La corresponsabilidad entre las actividades referidas en el presente artículo y las deduccione',
  NULL,
  195,
  NULL,
  NULL,
  NULL,
  'N',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00');
INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  2745,
  'S',
  '4401013',
  'Servicio de atención a víctimas en el exterior',
  'Comprende la elaboración e implementación del portafolio de actividades para las víctimas: representación judicial, asistencia material para garantizar su participación en las audiencias en la que sean requeridos (as), acompañamiento psicosocial, capacitación a líderes de las organizaciones de víctimas que se encuentren el exterior y a cónsules para que conozcan y tengan claridades sobre el  proceso para acceder a la Justicia Especial para la Paz para las victimas que residen fuera de Colombia.',
  NULL,
  195,
  NULL,
  NULL,
  NULL,
  'N',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00');
INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  2746,
  'S',
  '4401010',
  'Servicios de promoción en temáticas de la Jurisdicción Especial de la Paz',
  'Involucra todas las actividades de difusión, divulgación y posicionamiento (circulación) de las herramientas y contenidos de la Jurisdicción Especial para la Paz, teniendo en cuenta los grupos poblacionales a los que atiende la entidad. Además, los servicios de promoción incluirán también las actividades ligadas al diseño, producción y elaboración de  piezas y estrategias comunicativas que serán utilizadas, posteriormente, para la circulación de los contenidos de la Jurisdicción Especial para la Paz en diversos medios, plataformas y canales de participación. ',
  NULL,
  195,
  NULL,
  NULL,
  NULL,
  'N',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00');
INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  2747,
  'S',
  '4401009',
  'Servicio de información de la Jurisdicción Especial para la Paz implementado',
  'Dar a conocer a la población civil el avance y registro de los procesos de investigación, acusación, juzgamiento de la Jurisdicción Especial para la Paz a través de la grabación, intervención, producción, distribución y archivo de la información pública (audiencias) manejada en la Jurisdicción Especial para la Paz. De acuerdo a los artículos Transitorio 1, Parágrafo 1 y Transitorio 12 de la Constitución Política (Acto Legislativo 01 de 2017)',
  NULL,
  195,
  NULL,
  NULL,
  NULL,
  'N',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00');
INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  2748,
  'S',
  '4401015',
  'Servicio de apoyo en protección colectiva',
  'Consiste en la valoración de riesgo, definición e implementación de medidas de protección colectiva, de acuerdo al proyecto de Ley Estatutaria 08 de 2017, Art. 17, "De oficio o a solicitud de parte, por cuenta propia o a través del representante en la Jurisdicción Especial para la Paz se adoptarán medidas adecuadas y necesarias, conforme lo establezca la Ley procedimental, para proteger los derechos de los procesados, las víctimas, testigos e intervinientes que ante ella concurran, los cuales podrán ser vinculados a los programas de Protección de la Unidad Nacional de Protección con debido respeto de las garantías procesales, cuando sus derechos fundamentales a la vida y seguridad personal se encuentren amenazados por su participación en el proceso antes la Jurisdicción Especial para la Paz."',
  NULL,
  195,
  NULL,
  NULL,
  NULL,
  'N',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00');
INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  2749,
  'S',
  '4401014',
  'Servicio de apoyo en protección individual',
  'Consiste en la valoración de riesgo, definición e implementación de medidas de protección individual a víctimas, testigos, intervinientes, de acuerdo al proyecto de Ley Estatutaria 08 de 2017, Art. 17, "De oficio o a solicitud de parte, por cuenta propia o a tráves del representante en la Jurisdicción Especial para la Paz se adoptarán medidas adecuadas y necesarias, conforme lo establezca la Ley procedimental, para proteger los derechos de los procesados, las víctimas, testigos e intervinientes que ante ella concurran, los cuales podrán ser vinculados a los programas de Protección de la Unidad Nacional de Protección con debido respeto de las garantías procesales, cuando sus derechos fundamentales a la vida y seguridad personal se encuentren amenazados por su participación en el proceso antes la Jurisdicción Especial para la Paz."',
  NULL,
  195,
