INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  2752,
  'S',
  '4401005',
  'Documentos de planeación',
  'Documentos cuyo objetivo es plasmar una visión de futuro a nivel país, entidad territorial, comunidad, sector, región, entidad o cualquier nivel de desagregación que se requiera. Incluye objetivos, estrategias, metas e indicadores, además de aquellos documentos con el objetivo de dar una orientación frente a las acciones que el Estado debe realizar en el marco de una tema específico con el fin de suplir necesidades de interés público.',
