  'En cumplimiento del Numeral 2 del Artículo 2 del Decreto 588/17, corresponde al conjunto de actividades, iniciativas y procesos para el reconocimiento de las víctimas del conflicto armado interno como ciudadanos y sujetos políticos en perspectiva de dignificación, para el reconocimento voluntario de las responsabilidades por parte de los victimarios, y en general el reconocimiento por parte de toda la sociedad de las violaciones e infracciones producto del conflicto armado interno.',
