  2971,
  'S',
  '0301018',
  'Centros Integrados de Servicio - CIS',
  'Es una estrategia de gestión pública efectiva de Buen Gobierno, en la que entidades del orden nacional, distrital, departamental y municipal se organizan en un mismo espacio físico con el propósito de brindar su oferta a los ciudadanos. Esta Estrategia contribuye al goce efectivo de derechos mediante el acceso de toda la población a los trámites y servicios de las entidades vinculadas a los Centros. Los CIS operan bajo estándares que garantizan un trato amable, digno y eficiente con el objetivo de mejorar la satisfacción y percepción de los ciudadanos frente a los servicios del Estado.',
