  'Corresponde a un inmueble sobre el cual se realizan obras, operaciones y cuidados necesarios para su conservación en buen estado o en una situación determinada para evitar su degradación. Cuando es adelantado con recursos de inversión debe asegurarse de cumplir con las condiciones de una operación de inversión pública, es decir, debe orientarse a crear, ampliar o mantener la capacidad de producción del Estado, y contar claramente con actividades limitadas en el tiempo.',
